// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 1e36);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okFirstDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okFirstDeposit);
        vm.prank(actor);
        try c.withdraw() { } catch { assertTrue(false, "first withdraw must succeed"); }
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okSecondDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okSecondDeposit);
        bool okSecondWithdraw;
        vm.prank(actor);
        try c.withdraw() { okSecondWithdraw = true; } catch { okSecondWithdraw = false; }
        assertTrue(okSecondWithdraw);
    }
}
